INSERT INTO systems (id,name,short_name,country_code,country_name,region,authority,system_type,status,status_label,status_detail,signal_basis,confidence,timezone,official_url,last_checked_at,last_changed_at,freshness_minutes) VALUES ('tw-customs-clearance','Customs Clearance Operations','Taiwan Customs','TW','Taiwan','Asia-Pacific','Customs Administration, Ministry of Finance','customs','clear','Major maintenance upcoming','Taiwan Customs has scheduled a broad operational-host shutdown for 13 September 2026, 12:00–19:30 local time.','official_bulletin','official','Asia/Taipei','https://web.customs.gov.tw/multiplehtml/2222','2026-09-10T04:55:00Z','2026-09-01T00:00:00Z',1440) ON CONFLICT (id) DO NOTHING;
INSERT INTO systems (id,name,short_name,country_code,country_name,region,authority,system_type,status,status_label,status_detail,signal_basis,confidence,timezone,official_url,last_checked_at,last_changed_at,freshness_minutes) VALUES ('ph-e2m','Electronic-to-Mobile System','E2M','PH','Philippines','Asia-Pacific','Bureau of Customs','customs','clear','No recent advisory','The 2026 Bureau of Customs memorandum index is monitored for new MISTG E2M System Advisories. This is bulletin monitoring, not a continuous heartbeat.','official_bulletin','official','Asia/Manila','https://customs.gov.ph/memoranda-2026/','2026-09-10T04:55:00Z','2026-06-05T00:00:00Z',1440) ON CONFLICT (id) DO NOTHING;
