INSERT INTO events (id,system_id,country_code,country_name,region,event_type,status,severity,confidence,title,summary,operational_impact,workaround,starts_at,ends_at,resolved_at,all_day,source_name,source_url,source_tier,last_verified_at,recurrence,fingerprint) VALUES ('tw-customs-shutdown-20260913','tw-customs-clearance','TW','Taiwan','Asia-Pacific','scheduled_maintenance','upcoming','major','official','Taiwan customs operational host scheduled shutdown','Taiwan Customs will shut down its customs operational host on 13 September from 12:00 to 19:30 local time for an uninterruptible-power-system exercise.','The Customs-Port-Trade Single Window, online customs declaration and payment services, message processing/exchange, advance cargo information, tariff lookup, mobile customs platform and bonded smart-platform services will be suspended. The IoT monitoring platform stops from 11:00; the inbound passenger baggage system remains operational.','Complete time-sensitive declarations and messages before the window. Services may return early if the exercise finishes ahead of schedule.','2026-09-13T04:00:00Z','2026-09-13T11:30:00Z',NULL,FALSE,'Taiwan Customs Administration — system shutdown notice','https://web.customs.gov.tw/singlehtml/2222?cntId=6e19cac3015145688c33457567901c5d',1,'2026-09-10T04:55:00Z',NULL,'tw-customs-shutdown-20260913') ON CONFLICT (id) DO NOTHING;
